struct vector3d
{
  float x, y, z;
};

struct SoundLine
{
  vector3d start;
  vector3d stop;
};

struct WaveSoundEmitter
{
  SoundLine line;
  SoundLine segment[3];
  unsigned int numsegment;
};

enum SoundEmitterEnum
{
  WAVE_SE_FACE,
  WAVE_SE_SPLASH,
  WAVE_SE_TUBE
};

extern WaveSoundEmitter WAVE_SoundEmitter[];
__asm__(".equ WAVE_SoundEmitter, 0x00484BF8");

struct BeachData
{
  char padding[0xd0];
  bool bdir;
  char tail[0x143];
};

extern BeachData BeachDataArray[];
__asm__(".equ BeachDataArray, 0x0042C198");

struct game
{
  char padding[0x228];
  int beach_id;
};

extern game *g_game_ptr;
__asm__(".equ g_game_ptr, 0x0046AC64");

class KSReplay
{
  char padding[0x34];
  unsigned int playframe;

public:
  void MainEntityPos(vector3d &pos, int frame = -1);
  void WaveInfo(vector3d &pos, int &numTubes, float &mainTubeDist,
                float &secTubeDist, float &breakDist, int frame = -1);
};

__asm__(".equ MainEntityPos__8KSReplayR8vector3di, 0x0023CB00");

void KSReplay::WaveInfo(vector3d &pos, int &numTubes, float &mainTubeDist,
                        float &secTubeDist, float &breakDist, int frame)
{
  if (frame < 0)
    frame = playframe;

  bool left = BeachDataArray[g_game_ptr->beach_id].bdir;
  MainEntityPos(pos, frame);

  numTubes = WAVE_SoundEmitter[WAVE_SE_TUBE].numsegment;
  if (numTubes == 1)
  {
    if (left)
      mainTubeDist = WAVE_SoundEmitter[WAVE_SE_TUBE].segment[1].start.x - pos.x;
    else
      mainTubeDist = pos.x - WAVE_SoundEmitter[WAVE_SE_TUBE].segment[1].stop.x;
  }
  else
  {
    if (left)
      mainTubeDist = WAVE_SoundEmitter[WAVE_SE_TUBE].segment[2].start.x - pos.x;
    else
      mainTubeDist = pos.x - WAVE_SoundEmitter[WAVE_SE_TUBE].segment[1].stop.x;

    if (left)
      secTubeDist = pos.x - WAVE_SoundEmitter[WAVE_SE_TUBE].segment[1].stop.x;
    else
      secTubeDist = WAVE_SoundEmitter[WAVE_SE_TUBE].segment[2].start.x - pos.x;

    if (left)
      breakDist = pos.x - WAVE_SoundEmitter[WAVE_SE_TUBE].segment[1].start.x;
    else
      breakDist = WAVE_SoundEmitter[WAVE_SE_TUBE].segment[2].stop.x - pos.x;
  }
}
